def connect_page(port: int) -> websocket.WebSocket:
    tabs = json.load(urllib.request.urlopen(f"<redacted-url>", timeout=5))
    pages = [t for t in tabs if t["type"] == "page"]
    if not pages:
        raise SystemExit("✗ no page tabs open in the browser")

def to_wav(media: Path, wav: Path, ffmpeg: str) -> None:
    r = subprocess.run(
        [ffmpeg, "-y", "-loglevel", "error", "-i", str(media), "-vn", "-ar", "16000", "-ac", "1", str(wav)],
        capture_output=True,
    )
